import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Product.css';
import PageTitle from '../PageTitle';

function Product() {
  const [isModalOpen, setModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [products, setProducts] = useState([]); // Ürünleri saklayacağımız state
  const [filteredProducts, setFilteredProducts] = useState([]); // Filtrelenmiş ürünler
  const [loading, setLoading] = useState(true); // Yükleme durumunu kontrol etmek için state
  const [error, setError] = useState(null); // Hata durumu için state
  const [cart, setCart] = useState([]); // Sepet için state

  // Ürünleri API'den çekme
  useEffect(() => {
    axios.get('http://localhost:3001/api/products') // API URL'ini doğru girdiğinizden emin olun
      .then(response => {
        setProducts(response.data); // Gelen veriyi state'e ekle
        setFilteredProducts(response.data); // Filtrelenmiş ürünleri başta tüm ürünlerle eşitle
        setLoading(false); // Yükleme bitti
      })
      .catch(error => {
        console.error('Ürünler alınırken hata oluştu:', error);
        setError('Ürünler alınırken bir hata oluştu. Lütfen tekrar deneyin.'); // Hata mesajı
        setLoading(false);
      });
  }, []); // componentDidMount gibi çalışır, sadece ilk render'da çalışır

  // Modal'ı açma fonksiyonu
  const openModal = (product) => {
    setSelectedProduct(product);
    setModalOpen(true);
  };

  // Modal'ı kapama fonksiyonu
  const closeModal = () => {
    setModalOpen(false);
    setSelectedProduct(null);
  };

  // Filtreleme fonksiyonu
  const filterByCategory = (category) => {
    if (category === 'all') {
      setFilteredProducts(products); // 'all' seçildiğinde tüm ürünler gösterilsin
    } else {
      const filtered = products.filter(product => product.category === category); // Kategoriyi filtrele
      setFilteredProducts(filtered);
    }
  };

  // Sepete ürün ekleme fonksiyonu
  const addToCart = (product) => {
    setCart([...cart, product]); // Sepete ürünü ekle
    alert(`${product.name} sepete eklendi!`); // Kullanıcıya bilgi ver
  };

  return (
    <>
      <PageTitle title="Ürünümüz" />
      <div>
        <div className="baslik">Ürünümüz Hakkında</div>
        <div className="aboutcard">
          <div className="about-page">
            <h1 id="about-title">BeeonHive</h1>
            <p>
              BeeonHive ile birlikte kovanlarınızı web uygulamamız üzerinden kolayca takip edebilirsiniz. 2'si ana modül olmak üzere toplam
              6 modül ile birlikte kovanınızın sıcaklık ve nemini, karbondioksit ve sülfür oranını ve hatta GPS modülü ile konumunu öğrenebilirsiniz.
              Müdahale edilmesi gereken durumlarda ise gerekli ilaçlamayı da yapabilirsiniz.
            </p>
          </div>
        </div>
      </div>

      {/* Filtreleme butonları */}
      <div className="filter-buttons">
        <button onClick={() => filterByCategory('Ana Modül')}>Ana Modül</button>
        <button onClick={() => filterByCategory('Ek Modül')}>Ek Modül</button>
        <button onClick={() => filterByCategory('all')}>Tümü</button> {/* Tümünü görmek için */}
      </div>

      {/* Yükleme durumu */}
      <div className="product-container">
        {loading ? (
          <div className="loading-spinner">Yükleniyor...</div> // Burada bir yükleme animasyonu eklenebilir
        ) : error ? (
          <p>{error}</p> // Eğer hata varsa, hata mesajını göster
        ) : (
          filteredProducts.length > 0 ? (
            filteredProducts.map((product) => (
              <div className="product-box" key={product._id}> {/* _id kullanmaya dikkat et */}
                <img src={product.photo} alt={product.name} className="product-image" />
                <h3>{product.name}</h3>
                <p>{product.category}</p> {/* Kategoriyi burada ekliyoruz */}
                <p>{product.price} TL</p>
                <button onClick={() => openModal(product)}>Detayları Göster</button>
                <button onClick={() => addToCart(product)}>Sepete Ekle</button> {/* Sepete Ekle butonu */}
              </div>
            ))
          ) : (
            <p>Ürün bulunamadı.</p>  // Eğer ürün yoksa
          )
        )}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close" onClick={closeModal} aria-label="Modalı Kapat">×</button>
            <h2>{selectedProduct.name}</h2>
            <img src={selectedProduct.photo} alt={selectedProduct.name} className="product-image" />
            <p>{selectedProduct.productdetails}</p> {/* Ürün detaylarını burada göster */}
            <button className="close" onClick={closeModal}>Kapat</button>
          </div>
        </div>
      )}
    </>
  );
}

export default Product;
